import{_ as i,H as t,f as a,i as s}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"12 | 实战项目（二）：动手训练一个你自己的扩散模型","description":"","frontmatter":{},"headers":[{"level":2,"title":"关键知识串联","slug":"关键知识串联","link":"#关键知识串联","children":[]},{"level":2,"title":"训练扩散模型","slug":"训练扩散模型","link":"#训练扩散模型","children":[{"level":3,"title":"认识基础模块","slug":"认识基础模块","link":"#认识基础模块","children":[]},{"level":3,"title":"数据准备","slug":"数据准备","link":"#数据准备","children":[]},{"level":3,"title":"模型训练","slug":"模型训练","link":"#模型训练","children":[]},{"level":3,"title":"进阶到 diffusers 训练","slug":"进阶到-diffusers-训练","link":"#进阶到-diffusers-训练","children":[]}]},{"level":2,"title":"微调 Stable Diffusion","slug":"微调-stable-diffusion","link":"#微调-stable-diffusion","children":[]},{"level":2,"title":"如何调用各种 SD 模型？","slug":"如何调用各种-sd-模型","link":"#如何调用各种-sd-模型","children":[]},{"level":2,"title":"总结时刻","slug":"总结时刻","link":"#总结时刻","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI绘画核心技术与实战/12｜实战项目（二）：动手训练一个你自己的扩散模型.md","filePath":"AI绘画核心技术与实战/12｜实战项目（二）：动手训练一个你自己的扩散模型.md","lastUpdated":1795562124000}'),o={name:"AI绘画核心技术与实战/12｜实战项目（二）：动手训练一个你自己的扩散模型.md"};function r(l,e,n,p,d,u){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_12-实战项目-二-动手训练一个你自己的扩散模型" tabindex="-1">12 | 实战项目（二）：动手训练一个你自己的扩散模型 <a class="header-anchor" href="#_12-实战项目-二-动手训练一个你自己的扩散模型" aria-label="Permalink to &quot;12 | 实战项目（二）：动手训练一个你自己的扩散模型&quot;">​</a></h1><p>南柯</p><ul><li><p>课程介绍</p></li><li><p>讲述：潇然时长1 11:43大小10.71M</p></li></ul><p>你好，我是南柯。</p><p>前面几讲，我们已经了解了扩散模型的算法原理和组成模块，学习了 Stable Diffusion 模型新增的 CLIP 和 VAE 模块。掌握了这些知识，相信你也一定跃跃欲试，想要训练一个属于自己的 AI 绘画模型。</p><p>这一讲，我们会将前几讲的知识串联起来，从全局的视角讨论扩散模型如何训练和使用。我们将通过实战的形式，一起训练一个标准扩散模型，并微调一个 Stable Diffusion 模型，帮你进一步加深对知识的理解。学完这一讲，我们就迈出了模型自由的关键一步。</p><h2 id="关键知识串联" tabindex="-1">关键知识串联 <a class="header-anchor" href="#关键知识串联" aria-label="Permalink to &quot;关键知识串联&quot;">​</a></h2><p>在实战之前，我想请你思考一个问题：想要把标准的扩散模型升级为 Stable Diffusion，需要几步操作？</p><p>答案是两步。</p><p>我们通过第 6 讲已经知道，标准扩散模型的训练过程包含 6 个步骤，分别是随机选取训练图像、随机选择时间步 t、随机生成高斯噪声、一步计算第 t 步加噪图、使用 UNet 预测噪声值和计算噪声数值误差。</p><p>Stable Diffusion 在此基础上，增加了 VAE 模块和 CLIP 模块。VAE 模块的作用是降低输入图像的维度，从而加快模型训练、给 GPU 腾腾地方；CLIP 模块的作用则是将文本描述通过交叉注意力机制注入到 UNet 模块，让 AI 绘画模型做到言出法随。</p><p>我们不妨再翻出 Stable Diffusion 的算法框架图回忆一下。图中最左侧粉色区域便是 VAE 模块，最右侧的条件控制模块便可以是 CLIP（也可以是其他控制条件），而中间 UNet 部分展示的 QKV 模块，便是 prompt 通过交叉注意力机制引导图像生成。到此为止，是不是一切都串联起来了？</p><ul><li>图片来源：<a href="https://arxiv.org/abs/2112.10752" target="_blank" rel="noreferrer">https://arxiv.org/abs/2112.10752</a></li></ul><p>事实上，在 Stable Diffusion 中，还有很多其他黑魔法，比如无条件引导控制（Classifier-FreeGuidance）、引导强度（Guidance Scale）等，我们会在下一章进一步探讨。</p><p>知道了这些，我们不妨继续思考一个问题：训练一个标准扩散模型和 Stable Diffusion 模型，需要准备哪些“原材料”呢？</p><p>首先，我们需要 GPU，显存越大越好。没有英伟达显卡的同学，可以使用 Colab 免费的 15GT4 显卡。在第 10 讲中我们详细讨论了 Colab GPU 环境的用法，不熟悉的话你可以通过超链接回顾。</p><p>然后，我们需要训练数据。对于标准扩散模型而言，我们只需要纯粹的图片数据即可；对于Stable Diffusion，由于我们需要文本引导，就需要用到图片数据对应的文本描述。这里的文本描述既可以是像 CLIP 训练数据那种对应的文本描述，也可以是使用各种图片描述（imagecaption）模型获取的文本描述。</p><p>如果你要训练的是 Stable Diffusion，在第 1 讲中我们估算过，从头开始训练的成本差不多是几套海淀学区房的价格，所以我们最好是基于某个开源预训练模型进行针对性微调。事实上，开源社区里大多数模型都是微调出来的。</p><p>此外，对于 Stable Diffusion，我们还需要准备好预先训练好的 CLIP 模型和 VAE 模型。</p><p>关于训练数据、开源预训练模型、CLIP 和 VAE，你都不必担心。后面的代码环节我会说明获取方法。现在你只需要准备好 GPU 资源即可。</p><p>这一讲的实战部分，所有操作你都可以通过点开我提供的Colab 链接来完成。当然，我更推荐你新建全新的 Colab，对照我提供的原始 Colab 逐步写代码来完成。这样有助于你加深对训练过程的理解。</p><h2 id="训练扩散模型" tabindex="-1">训练扩散模型 <a class="header-anchor" href="#训练扩散模型" aria-label="Permalink to &quot;训练扩散模型&quot;">​</a></h2><p>这里我们通过两种方式来训练扩散模型。</p><p>第一种是使用 denoising_diffusion_pytorch 这个高度集成的工具包，第二种则是基于 diffusers这种更多开发者使用的工具包。对于专业的算法同学而言，我更推荐使用 diffusers 来训练。原因是 diffusers 工具包在实际的 AI 绘画项目中用得更多，并且也更易于我们修改代码逻辑，实现定制化功能。</p><h3 id="认识基础模块" tabindex="-1">认识基础模块 <a class="header-anchor" href="#认识基础模块" aria-label="Permalink to &quot;认识基础模块&quot;">​</a></h3><p>先看第一种训练方式，我们先按照下面的方式，在 Colab 里安装对应工具包。你可以直接点开我的 Colab 链接，点击播放按键逐步操作。</p><ul><li>1pip install denoising diffusion pytorch</li></ul><p>这个工具包中提供了 UNet 和扩散模型两个封装好的模块，你可以通过两行指令创建 UNet，并基于创建好的 UNet 创建一个完整的扩散模型，同时指定了图像分辨率和总的加噪步数。</p><ul><li>1from denoising_diffusion_pytorch import Unet, GaussianDiffusion2import torch34model = Unet(5dim = 64,6dim_mults = (1, 2, 4, 8)7).cuda()89diffusion = GaussianDiffusion(10model,11image_size = 128,12timesteps = 1000 # number of steps13).cuda()</li></ul><p>训练过程也非常清爽，为了帮你更好地理解一次训练的过程是怎样的。我们结合代码例子看一下，比如我们随机初始化八张图片，便可以通过后面这两行代码完成扩散模型的一次训练。</p><ul><li><h1 id="使用随机初始化的图片进行一次训练12training-images-torch-randn-8-3-128-128-3loss-diffusion-training-images-cuda-4loss-backward" tabindex="-1">使用随机初始化的图片进行一次训练12training_images = torch.randn(8, 3, 128, 128)3loss = diffusion(training_images.cuda())4loss.backward() <a class="header-anchor" href="#使用随机初始化的图片进行一次训练12training-images-torch-randn-8-3-128-128-3loss-diffusion-training-images-cuda-4loss-backward" aria-label="Permalink to &quot;使用随机初始化的图片进行一次训练12training_images = torch.randn(8, 3, 128, 128)3loss = diffusion(training_images.cuda())4loss.backward()&quot;">​</a></h1></li></ul><p>如果你想用自己本地的图像，而非随机初始化的图像，可以参考下面的代码。</p><ul><li><p>1from PIL import Image2import torchvision.transforms as transforms3import torch# 预设一个变换操作，将PIL Image转换为PyTorch Tensor，并对其进行归一化45transform = transforms.Compose([</p></li><li><p>6transforms.Resize((128, 128)),7transforms.ToTensor(),8])# 我们认为你有个列表包含了8张图像的路径910image_paths = [&#39;path_to_your_image1&#39;, &#39;path_to_your_image2&#39;, &#39;path_to_your_image311&#39;path_to_your_image5&#39;, &#39;path_to_your_image6&#39;, &#39;path_to_your_image7# 使用List comprehension读取并处理这些图片1213images = [transform(Image.open(image_path)) for image_path in image_paths]# 将处理好的图像List转化为一个4D Tensor，注意torch.stack能够自动处理3D Tensor到4D Tensor1415training_images = torch.stack(images)# 现在training_images应该有8张3x128x128的图像1617print(training_images.shape) # torch.Size([8, 3, 128, 128])</p></li></ul><p>训练完成后，可以直接使用得到的模型来生成图像。由于我们的模型只训练了一步，模型的输出也是纯粹的噪声图。这里只是为了让你找一下手感。</p><ul><li>1sampled_images = diffusion.sample(batch_size = 4)</li></ul><h3 id="数据准备" tabindex="-1">数据准备 <a class="header-anchor" href="#数据准备" aria-label="Permalink to &quot;数据准备&quot;">​</a></h3><p>理解完基本流程，我们使用真实数据进行一次训练。我们以 oxford-flowers 这个数据集为例，首先需要安装 datasets 这个工具包。</p><ul><li>1pip install datasets</li></ul><p>我们使用后面的代码就可以下载这个数据集，并将数据集中所有的图片单独存储成 png 格式，用 png 格式更方便我们查看。全部处理完大概有 8000 张图片。</p><ul><li><p>1from PIL import Image2from io import BytesIO3from datasets import load_dataset</p></li><li><p>4import os5from tqdm import tqdm67dataset = load_dataset(&quot;nelorth/oxford-flowers&quot;)8# 创建一个用于保存图片的文件夹910images_dir = &quot;./oxford-datasets/raw-images&quot;11os.makedirs(images_dir, exist_ok=True)12# 遍历所有图片并保存，针对oxford-flowers，整个过程要持续15分钟左右1314for split in dataset.keys():15for index, item in enumerate(tqdm(dataset[split])):16image = item[&#39;image&#39;]17image.save(os.path.join(images_dir, f&quot;{split}<em>image</em>{index}.png&quot;))</p></li></ul><p>你也可以在 Hugging Face 上挑选你喜欢的图像数据集，挑选和使用方法可以参考后面的截图。</p><p>点击数据集使用后，通过下面两行代码即可完成数据集的下载和读取。</p><ul><li>1from datasets import load_dataset2dataset = load_dataset(&quot;nelorth/oxford-flowers&quot;)</li></ul><p>比方说上图展示的这个数据集，里面都是一些不同的花朵。我们课程里就选择这个花朵数据集，训练的目的就是得到一个扩散模型，这个模型可以从噪声出发，逐步去噪得到一朵花。</p><h3 id="模型训练" tabindex="-1">模型训练 <a class="header-anchor" href="#模型训练" aria-label="Permalink to &quot;模型训练&quot;">​</a></h3><p>准备工作完成，我们便可以通过以下代码来进行完整训练。如果你的 GPU 不够强大，可以根据实际情况调整训练的 batch_size 大小。</p><ul><li>1import torch2from denoising_diffusion_pytorch import Unet, GaussianDiffusion, Trainer34model = Unet(5dim = 64,6dim_mults = (1, 2, 4, 8)7).cuda()89diffusion = GaussianDiffusion(10model,11image_size = 128,12timesteps = 1000 # 加噪总步数13).cuda()1415trainer = Trainer(16diffusion,17&#39;./oxford-datasets/raw-images&#39;,18train_batch_size = 16,19train_lr = 2e-5,20train_num_steps = 20000, # 总共训练20000步21gradient_accumulate_every = 2, # 梯度累积步数22ema_decay = 0.995, # 指数滑动平均decay参数23amp = True, # 使用混合精度训练加速24calculate_fid = False, # 我们关闭FID评测指标计算（比较耗时）。FID用于评测生25save_and_sample_every = 2000 # 每隔2000步保存一次模型26)2728trainer.train()</li></ul><p>这里分享一个小技巧，如果在使用 GPU 的时候报错提示显存不足，可以通过后面的命令手工释放不再使用的 GPU 显存。</p><ul><li>1import gc2del old_model # 这里的old_model是指已经不会再用到的模型34gc.collect()5torch.cuda.empty_cache()</li></ul><p>对于 16G 的 V100 显卡而言，整个任务的训练要持续 3 至 4 个小时。在整个训练过程中，每次间隔 2000 个训练步，我们会保存一次模型权重，并利用当前权重进行图像的生成。</p><p>你可以参考后面的图片，能看出，随着训练步数的增多，这个扩散模型的图像生成能力在逐渐变强。</p><h3 id="进阶到-diffusers-训练" tabindex="-1">进阶到 diffusers 训练 <a class="header-anchor" href="#进阶到-diffusers-训练" aria-label="Permalink to &quot;进阶到 diffusers 训练&quot;">​</a></h3><p>对于我们提到的第二种扩散模型训练方式，基于 diffusers 工具包的训练，我们要写的代码就会多得多，并且可调节的参数也会多很多。</p><p>这里我放一个 Colab 的链接，包含完整的训练代码。我来带你一起拆解下其中的关键部分。</p><p>首先，我们看数据集的使用。通过 datasets 工具包加载数据集，与denoising_diffusion_pytorch 的训练不同，在 diffusers 训练模式下，我们不需要将数据集再转为本地图片格式。</p><ul><li>1import torch2from datasets import load_dataset3# 加载数据集45config.dataset_name = &quot;huggan/smithsonian_butterflies_subset&quot;6dataset = load_dataset(config.dataset_name, split=&quot;train&quot;)7# 封装成训练用的格式89train_dataloader = torch.utils.data.DataLoader(dataset, batch_size=config.train_b</li></ul><p>为了提升模型的性能，我们可以对图像数据进行数据增广。所谓数据增广，就是对图像做一些随机左右翻转、随机颜色扰动等操作，目的是增强训练数据的多样性。</p><ul><li><p>1from torchvision import transforms23preprocess = transforms.Compose(4[5transforms.Resize((config.image_size, config.image_size)),</p></li><li><p>6transforms.RandomHorizontalFlip(),7transforms.ToTensor(),8transforms.Normalize([0.5], [0.5]),9]10)</p></li></ul><p>然后我们看 UNet 结构。按照下图的结构搭建 UNet 模块，比如图中输入和输出的分辨率都是128x128，在实际 UNet 搭建中你可以任意指定。</p><p>我们可以通过下面的代码来创建 UNet 结构。</p><ul><li>1from diffusers import UNet2DModel23model = UNet2DModel(sample_size=config.image_size, # 目标图像的分辨率4in_channels=3, # 输入通道的数量，对于RGB图像为35out_channels=3, # 输出通道的数量6layers_per_block=2, # 每个UNet块中使用的ResNet层的数量7block_out_channels=(128, 128, 256, 256, 512, 512), # 每个UNet块的输出通道数量89down_block_types=(&quot;DownBlock2D&quot;, # 常规的ResNet下采样块1011&quot;DownBlock2D&quot;,12&quot;DownBlock2D&quot;,13&quot;DownBlock2D&quot;,&quot;AttnDownBlock2D&quot;, # 具有空间自注意力的ResNet下采样块1415&quot;DownBlock2D&quot;,16),17up_block_types=(&quot;UpBlock2D&quot;, # 常规的ResNet上采样块18&quot;AttnUpBlock2D&quot;, # 具有空间自注意力的ResNet上采样块1920&quot;UpBlock2D&quot;,21&quot;UpBlock2D&quot;,22&quot;UpBlock2D&quot;,23&quot;UpBlock2D&quot;24),25)</li></ul><p>可以看到，使用 diffusers 创建 UNet 的步骤要比 denoising_diffusion_pytorch 复杂很多，好处是给工程师带来了更大的灵活性。</p><p>接下来我们看采样器的用法。这里需要确定我们加噪用的采样器，帮助我们通过一步计算得到第 t 步的加噪结果。</p><ul><li>1from diffusers import DDPMScheduler23noise_scheduler = DDPMScheduler(num_train_timesteps=1000)4# 一步加噪的计算56noise = torch.randn(sample_image.shape)7timesteps = torch.LongTensor([50])8noisy_image = noise_scheduler.add_noise(sample_image, noise, timesteps)</li></ul><p>接着通过模型预测噪声，并计算损失函数。</p><ul><li>1import torch.nn.functional as F23noise_pred = model(noisy_image, timesteps).sample4loss = F.mse_loss(noise_pred, noise)</li></ul><p>最后，我们将这些模块串联起来，便可以得到基于 diffusers 训练扩散模型的核心代码。</p><ul><li><p>1for epoch in range(num_epochs):2for step, batch in enumerate(train_dataloader):3clean_images = batch[&#39;images&#39;]# 对应于扩散模型训练过程：随机采样噪声45noise = torch.randn(clean_images.shape).to(clean_images.device)6bs = clean_images.shape[0]7# 对应于扩散模型训练过程：对于batch中的每张图，随机选取时间步t89timesteps = torch.randint(0, noise_scheduler.num_train_timesteps, (bs,),10</p></li><li><h1 id="对应于扩散模型训练过程-一步计算加噪结果1112noisy-images-noise-scheduler-add-noise-clean-images-noise-timesteps-1314with-accelerator-accumulate-model-对应于扩散模型训练过程-预测噪声值并计算损失函数1516noise-pred-model-noisy-images-timesteps-return-dict-false-0-17loss-f-mse-loss-noise-pred-noise-18accelerator-backward-loss-19optimizer-step" tabindex="-1">对应于扩散模型训练过程：一步计算加噪结果1112noisy_images = noise_scheduler.add_noise(clean_images, noise, timesteps)1314with accelerator.accumulate(model):# 对应于扩散模型训练过程：预测噪声值并计算损失函数1516noise_pred = model(noisy_images, timesteps, return_dict=False)[0]17loss = F.mse_loss(noise_pred, noise)18accelerator.backward(loss)19optimizer.step() <a class="header-anchor" href="#对应于扩散模型训练过程-一步计算加噪结果1112noisy-images-noise-scheduler-add-noise-clean-images-noise-timesteps-1314with-accelerator-accumulate-model-对应于扩散模型训练过程-预测噪声值并计算损失函数1516noise-pred-model-noisy-images-timesteps-return-dict-false-0-17loss-f-mse-loss-noise-pred-noise-18accelerator-backward-loss-19optimizer-step" aria-label="Permalink to &quot;对应于扩散模型训练过程：一步计算加噪结果1112noisy_images = noise_scheduler.add_noise(clean_images, noise, timesteps)1314with accelerator.accumulate(model):# 对应于扩散模型训练过程：预测噪声值并计算损失函数1516noise_pred = model(noisy_images, timesteps, return_dict=False)[0]17loss = F.mse_loss(noise_pred, noise)18accelerator.backward(loss)19optimizer.step()&quot;">​</a></h1></li></ul><h2 id="微调-stable-diffusion" tabindex="-1">微调 Stable Diffusion <a class="header-anchor" href="#微调-stable-diffusion" aria-label="Permalink to &quot;微调 Stable Diffusion&quot;">​</a></h2><p>搞定了扩散模型的训练，我们可以再挑战一下 Stable Diffusion 模型的微调。我们可以直接参考 diffusers 官方提供的训练代码，别看这个代码有接近 1100 行，其实相比于上面提到的标准扩散模型训练，核心也只是多了 VAE 和 CLIP 的部分。</p><p>这里我节选了 VAE 和 CLIP 部分的代码，目的是让你了解这两个模块是如何加载使用的。</p><ul><li>1tokenizer = CLIPTokenizer.from_pretrained(2args.pretrained_model_name_or_path, subfolder=&quot;tokenizer&quot;, revision=args.revi3)45text_encoder = CLIPTextModel.from_pretrained(6args.pretrained_model_name_or_path, subfolder=&quot;text_encoder&quot;, revision=args.r7)89vae = AutoencoderKL.from_pretrained(10args.pretrained_model_name_or_path, subfolder=&quot;vae&quot;, revision=args.revision11)1213unet = UNet2DConditionModel.from_pretrained(14args.pretrained_model_name_or_path, subfolder=&quot;unet&quot;, revision=args.non_ema_r15)16# 将vae 和 text_encoder的参数冻结，训练过程中权重不更新1718vae.requires_grad_(False)19text_encoder.requires_grad_(False)</li></ul><p>你可能在代码中发现了一个 tokenizer 变量。它的作用便是我们在第 7 讲中提到的，对我们输入的 prompt 进行分词后获取 token_id。有了 token_id，我们便可以获取模型可用的词嵌入向量。CLIP 模型的文本编码器（text_encoder）基于词嵌入向量，便可以提取文本特征。VAE 模块和 CLIP 模块都不需要权重更新，因此上面的代码中将梯度（grad）设置为 False。</p><p>这里我需要指出，在一些情况下，比如训练 DreamBooth 和 LoRA 模型时，CLIP 文本编码器的参数也可以学习和更新，这能帮我们提升模型的效果。</p><p>最后，我们再看看 Stable Diffusion 训练的核心代码。</p><ul><li>1for epoch in range(num_train_epochs):2for step, batch in enumerate(train_dataloader):3# VAE模块将图像编码到潜在空间45latents = vae.encode(batch[&quot;pixel_values&quot;].to(weight_dtype)).latent_dist6# 随机噪声 &amp; 加噪到第t步78noise = torch.randn_like(latents)9timesteps = torch.randint(0, noise_scheduler.config.num_train_timesteps)10noisy_latents = noise_scheduler.add_noise(latents, noise, timesteps)11# 使用CLIP将文本描述作为输入1213encoder_hidden_states = text_encoder(batch[&quot;input_ids&quot;])[0]14target = noise15# 预测噪声并计算loss1617model_pred = unet(noisy_latents, timesteps, encoder_hidden_states).sampl18loss = F.mse_loss(model_pred.float(), target.float(), reduction=&quot;mean&quot;)19optimizer.step()</li></ul><p>相信你在上面的代码中看到了很多熟悉的名词，VAE、潜在空间、CLIP、文本描述等，这些都是 Stable Diffusion 比标准扩散模型多出来的东西。如果你想进一步确认文本描述如何通过交叉注意力机制起作用，我推荐你去看看 UNet2DConditionModel 这个模块的代码，加深理解。</p><h2 id="如何调用各种-sd-模型" tabindex="-1">如何调用各种 SD 模型？ <a class="header-anchor" href="#如何调用各种-sd-模型" aria-label="Permalink to &quot;如何调用各种 SD 模型？&quot;">​</a></h2><p>其实我们可以在 Hugging Face 中找到各种现成的模型，我们只需通过模型的 model_id，便可以直接在 Colab 中调用这些模型，我们这就实战练习一下。</p><p>比如我们可以使用 Counterfeit-V2.5 这个模型，首先获取到它的 model_id。</p><p>之后，我们通过后面的代码下载并加载模型。第四行的模型 ID 可以灵活调整，你可以切换成你心仪的模型。</p><ul><li>1import torch2from diffusers import DiffusionPipeline3from diffusers import DDIMScheduler, DPMSolverMultistepScheduler, EulerAncestralD4pipeline = DiffusionPipeline.from_pretrained(&quot;gsdf/Counterfeit-V2.5&quot;)</li></ul><p>然后用下面代码完成切换采样器，prompt 设置等操作，便可以随心所欲地创作了。</p><ul><li><h1 id="切换为dpm采样器12pipeline-scheduler-dpmsolvermultistepscheduler-from-config-pipeline-scheduler-c34prompt-masterpiece-best-quality-1girl-solo-animal-ears-rabbit-5negative-prompt-easynegative-extra-fingers-fewer-fingers-6images-pipeline-prompt-width-512-height-512-num-inference-steps-20-guid" tabindex="-1">切换为DPM采样器12pipeline.scheduler = DPMSolverMultistepScheduler.from_config(pipeline.scheduler.c34prompt = &quot;((masterpiece,best quality)),1girl, solo, animal ears, rabbit&quot;5negative_prompt = &quot;EasyNegative, extra fingers,fewer fingers,&quot;6images = pipeline(prompt, width = 512, height = 512, num_inference_steps=20, guid <a class="header-anchor" href="#切换为dpm采样器12pipeline-scheduler-dpmsolvermultistepscheduler-from-config-pipeline-scheduler-c34prompt-masterpiece-best-quality-1girl-solo-animal-ears-rabbit-5negative-prompt-easynegative-extra-fingers-fewer-fingers-6images-pipeline-prompt-width-512-height-512-num-inference-steps-20-guid" aria-label="Permalink to &quot;切换为DPM采样器12pipeline.scheduler = DPMSolverMultistepScheduler.from_config(pipeline.scheduler.c34prompt = &quot;((masterpiece,best quality)),1girl, solo, animal ears, rabbit&quot;5negative_prompt = &quot;EasyNegative, extra fingers,fewer fingers,&quot;6images = pipeline(prompt, width = 512, height = 512, num_inference_steps=20, guid&quot;">​</a></h1></li></ul><p>你可以点开我的 Colab 链接进行操作。可以在 Hugging Face 中调一些你喜欢的 AI 绘画模型，试试自己动手创作一些作品。</p><h2 id="总结时刻" tabindex="-1">总结时刻 <a class="header-anchor" href="#总结时刻" aria-label="Permalink to &quot;总结时刻&quot;">​</a></h2><p>今天我们通过实战的形式加深了对扩散模型和 Stable Diffusion 模型的认识。在扩散模型部分，我们从数据准备开始，使用两种不同的形式从头开始进行模型训练，最终殊途同归，都能得到“不听话”的 AI 画师。</p><p>为了进一步调优，我们又引入 VAE 和 CLIP 模块，在开源 Stable Diffusion 模型的基础上，微调属于我们自己的 SD 模型，并深入探讨了其中的代码细节。我们也探索了如果通过代码直接使用开源社区提供的 SD 模型，通过短短几行代码就能实现 AI 绘画。</p><p>在我看来，以扩散模型为主的 AI 绘画，与此前 GAN 时代最大的不同之处便是“不可小觑的开源社区”。2022 年之前，各种有趣的 GAN 模型和特效更多像是企业才“玩得动”的技术，而如今的 AI 绘画则是在放大每一个爱好者的创造力。</p><p>当前，企业会选择当前效果最好的开源模型，比如 SDXL、AnythingV5 漫画模型等，进一步构造海量的高质量数据，去微调这些 SD 模型。技术方案和我们今天实战部分微调 SD 模型是一样的，只不过企业有更多的 GPU、图片数据和标注员。</p><p>即便如此，为什么开源社区的模型仍旧有如此抢眼的表现呢？我个人觉得，相比很多企业的KPI 驱动，开源社区兴趣驱动更容易做出垂类精品。如果你也有类似的感觉，那么期待你和我一起，去做一些有意思的 AI 绘画模型。</p><p>这一讲的重点，你可以点开下面的导图进行知识回顾。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>这一讲是我们的实战课。我们留一个实战任务。在 Hugging Face 中选择一个你喜欢的基础模型，通过写代码的方式生成一组你喜欢的图片。</p><p>期待你在留言区和我交流互动，也推荐你把今天的内容分享给身边的小伙伴，一起创造更有个性的 AI 绘画模型。</p><ul><li><p>分享给好友，一起充电成长</p></li><li><p>赞 6</p></li></ul><p>2023-08-11</p><ul><li><p>提建议</p></li><li><p>11｜VAE系列：如何压缩图像给GPU腾腾地方</p></li></ul><p>上一篇</p><ul><li>答疑课堂1｜热点问题答疑&amp;前两章思考题答案</li></ul><p>下一篇</p>',101)])])}const f=i(o,[["render",r]]);export{c as __pageData,f as default};
